struct Node {
    long long len;
    long long lazy;
    long long id;
    Node() : len(0), lazy(1) {}
};
const int maxn = 1e6+ 5;
Node seg[maxn];
Node operator+(const Node &a, const Node &b) {
    Node res;
    res.len = a.len + b.len;
    return res;
}
void propagate(int id) {
    if (seg[id].lazy != 1) {
        seg[id * 2].lazy *= seg[id].lazy;
        seg[id * 2 + 1].lazy *= seg[id].lazy;
        seg[id *2].len *= seg[id].lazy;
        seg[id *2 + 1].len *= seg[id].lazy;
        seg[id].lazy = 1;
    }
}
void update2(int id, int l, int r, int ql, int qr, long long val) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        seg[id].len += val;
        return;
    }
    propagate(id);
    int mid = (l + r) / 2;
    update2(id * 2, l, mid, ql, qr, val);
    update2(id * 2 + 1, mid + 1, r, ql, qr, val);
    seg[id] = seg[id * 2] + seg[id * 2 + 1];
}
void update(int id, int l, int r, int ql, int qr, long long val) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        seg[id].len *= val;
        seg[id].lazy *= val;
        return;
    }
    propagate(id);
    int mid = (l + r) / 2;
    update(id * 2, l, mid, ql, qr, val);
    update(id * 2 + 1, mid + 1, r, ql, qr, val);
    seg[id] = seg[id * 2] + seg[id * 2 + 1];
}
Node query(int id, int l, int r, int ql, int qr) {
    if (ql > r || qr < l) return Node();
    if (ql <= l && r <= qr) {
        return seg[id];
    }
    propagate(id);
    int mid = (l + r) / 2;
    return query(id * 2, l, mid, ql, qr) + query(id * 2 + 1, mid + 1, r, ql, qr);
}
void build(int id, int l, int r) {
    if (l == r) {
        seg[id] = Node();
        seg[id].len = 1;
        seg[id].id = l;
        return;
    }
    int mid = (l + r) / 2;
    build(id * 2, l, mid);
    build(id * 2 + 1, mid + 1, r);
    seg[id] = seg[id * 2] + seg[id * 2 + 1];
}
pair<long long, long long> find_kth(int id, int l, int r, long long k) {
    if (l == r) return {l, id};
    propagate(id);
    int mid = (l + r) / 2;
    if (seg[id * 2].len >= k) {
        return find_kth(id * 2, l, mid, k);
    } else {
        return find_kth(id * 2 + 1, mid + 1, r, k - seg[id * 2].len);
    }
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    long long n, q;
    cin >> n >> q;
    string s;
    cin >> s;
    build(1, 1, n);
    while(q--) {
        int type;
        cin >> type;
        if (type == 1) {
            long long l, r, val;
            cin >> l >> r;
            auto[l_, idl] = find_kth(1, 1, n, l);
            auto[r_, idr] = find_kth(1, 1, n, r);
            debug(l_, r_, idl, idr);
            long long tmp = query(1, 1, n, 1, l_).len;
            debug(l_, tmp - l + 1);
            long long tmp1 = query(1, 1, n, r_, n).len;
            if(l_ == r_) {
                update2(1, 1, n, l_, l_, r - l + 1);
            } else {
                debug(tmp1, r, (seg[1].len - r), tmp1 - (seg[1].len - r));
                update2(1, 1, n, r_, r_, tmp1 - (seg[1].len - r));
                debug(l_, tmp - l + 1);
                update2(1, 1, n, l_, l_, tmp - l + 1);
            }
            val = 2;
            if(l_ + 1 <= r_ - 1)
            update(1, 1, n, l_ + 1, r_ - 1, val);
            #ifndef ONLINE_JUDGE
            for(int i = 1; i <= seg[1].len; i++) {
                auto[pos, id] = find_kth(1, 1, n, i);
                cerr << s[pos - 1];
            }
            cerr << "\n";
            #endif
        } else if (type == 2) {
            long long ind;
            cin >> ind;
            auto[pos, id] = find_kth(1, 1, n, ind);
            cout << s[pos - 1] << "\n";
        }

    }
}